// controllers/notification.controller.js
import prisma from "../lib/db.js";

const NOTIFICATION_TYPES = ["info", "warning", "success", "error"];

// Create a notification. Notifications are system-generated by the controllers;
// this endpoint only lets a user create one for themselves.
export const createNotification = async (req, res) => {
  try {
    const { title, message, type } = req.body;

    if (!title || !message || typeof title !== "string" || typeof message !== "string") {
      return res.status(400).json({ success: false, message: "title and message are required" });
    }
    if (type !== undefined && !NOTIFICATION_TYPES.includes(type)) {
      return res.status(400).json({ success: false, message: "Invalid notification type" });
    }

    const notification = await prisma.notification.create({
      data: {
        userId: req.user._id,
        title,
        message,
        type: type || "info",
      },
    });

    notification._id = notification.id;
    res.status(201).json({ success: true, notification });
  } catch (err) {
    console.error("Error creating notification:", err);
    res.status(500).json({ success: false, message: "Failed to create notification" });
  }
};

// Get all notifications for a user
export const getUserNotifications = async (req, res) => {
  try {
    const notifications = await prisma.notification.findMany({
      where: { userId: req.user._id },
      orderBy: { createdAt: "desc" },
    });
    notifications.forEach((n) => (n._id = n.id));
    res.json({ success: true, notifications });
  } catch (err) {
    console.error("Error fetching notifications:", err);
    res.status(500).json({ success: false, message: "Failed to fetch notifications" });
  }
};

// Delete a notification (only your own)
export const deleteNotification = async (req, res) => {
  try {
    const { notificationId } = req.params;
    const result = await prisma.notification.deleteMany({
      where: { id: notificationId, userId: req.user._id },
    });
    if (result.count === 0) {
      return res.status(404).json({ success: false, message: "Notification not found" });
    }
    res.json({ success: true, message: "Notification deleted" });
  } catch (err) {
    console.error("Error deleting notification:", err);
    res.status(500).json({ success: false, message: "Failed to delete notification" });
  }
};

// Mark all of the caller's notifications as read
export const markAllRead = async (req, res) => {
  try {
    await prisma.notification.updateMany({
      where: { userId: req.user._id, isRead: false },
      data: { isRead: true },
    });
    res.json({ success: true });
  } catch (err) {
    console.error("Error marking notifications read:", err);
    res.status(500).json({ success: false, message: "Failed to update notifications" });
  }
};
